css:
*{box-sizing:border-box}
html{overflow-y:scroll}
body{margin:0;color:#181818;background:#fafafa;font:12px/1.35 system-ui,sans-serif}
#feature{width:100%;padding:8px 12px 32px}
.control-panes{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;align-items:start;min-width:0;overflow:visible}
.pane{min-width:0;overflow:visible}
.pane-head{position:sticky;top:0;z-index:2;display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin:0 0 7px;padding:7px 2px 6px;background:rgba(250,250,250,.96);border-bottom:1px solid #ddd}
.pane-title{font:650 12px/1.35 system-ui,sans-serif}
.pane-meta{color:#777;font:9px/1.45 ui-monospace,monospace}
.tree,.children{display:grid;gap:3px}
.children{margin:3px 0 0 14px;padding-left:10px;border-left:1px solid #d8d8d8}
.children[hidden]{display:none}
.node{padding:1px 0}
.row,.properties{display:flex;align-items:baseline;gap:3px}
.row{align-items:flex-start;min-height:22px}
.properties{min-width:0;flex:1;flex-wrap:wrap}
.property{padding:0 4px;border:0;border-radius:999px;background:#f2f2f2;color:#777;font:9px/1.45 ui-monospace,monospace;text-align:left}
.property[data-variant=title]{order:-2;background:transparent;color:#181818;font:650 12px/1.35 system-ui,sans-serif}
.property[data-key=id]{order:-1;color:#333}
.property[data-key=state][data-value=active]{color:#1f5d31;background:#edf6ef}
.property[data-key=state][data-value=inactive]{color:#8b3030;background:#faeeee}
.property[data-missing=true]{background:transparent;color:#aaa;font-style:italic}
.relation-controls{display:flex;flex:none;align-items:center;gap:3px;margin-left:auto;white-space:nowrap}
.relation-toggle{padding:0 4px;border:0;border-radius:999px;background:#eceff3;color:#526070;font:9px/1.45 ui-monospace,monospace;cursor:pointer}
@media(max-width:640px){#feature{padding:6px 8px}.control-panes{gap:7px}.children{margin-left:7px;padding-left:7px}.pane-meta{display:none}}
